// Thai is the source language: UI strings are written in Thai in the code and looked up here for English.
// A missing entry falls back to the Thai text, so a forgotten string shows Thai instead of breaking.
// Place facts that only exist in Thai (descriptions, notes, free-text hours) stay Thai and are marked lang="th".
let current='th';
export const getLang=()=>current;
export const setLangValue=value=>{current=value==='en'?'en':'th';return current;};
export const locale=()=>current==='en'?'en-GB':'th-TH';
const fill=(text,vars)=>vars?text.replace(/\{(\w+)\}/g,(m,k)=>k in vars?String(vars[k]):m):text;
export function t(th,vars){return fill(current==='en'&&EN[th]!=null?EN[th]:th,vars);}
// English for a Thai term whatever the current language (used so English words also find places in search)
export const english=th=>EN[th]||'';
// "{n} แห่ง" needs a singular in English
export const placesCount=n=>current==='en'?`${n} ${n===1?'place':'places'}`:`${n} แห่ง`;

